[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ExpectedOldHead,[Parameter(Mandatory=$true)][string]$ExpectedReleaseHead,[Parameter(Mandatory=$true)][string]$ReleaseCandidateRoot,[Parameter(Mandatory=$true)][string]$ReleasePython,[Parameter(Mandatory=$true)][string]$BackupManifest,[switch]$Execute,[string]$ApprovalPhrase,[switch]$Simulation,[string]$SimulationRoot='C:\VAMBAM\Projects\OTG\DEV\production_tooling_sandbox_107',[int]$SimulationPort=18502)
$ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'production_update_common.ps1'); if($Simulation){Assert-Simulation $SimulationRoot $SimulationPort; if(-not $Execute){'MODE=DRY_RUN';'SIMULATION=YES';'MAIN_PROMOTION_REQUIRED=YES';'MUTATION_EXECUTED=NO';exit 0}; Assert-Approval $Execute $ApprovalPhrase 'UPDATE_OTG_ANALYTICS_8502'; if(-not(Test-Path $BackupManifest)){throw 'BACKUP_MANIFEST_REQUIRED'}; $m=Get-Content $BackupManifest -Raw|ConvertFrom-Json; if(-not $m.backup_complete){throw 'BACKUP_MANIFEST_INVALID'}; $state=Join-Path $SimulationRoot 'state';New-Item -ItemType Directory -Path $state -Force|Out-Null; 'MIGRATION_1=PASS'|Set-Content (Join-Path $state 'migration.log'); 'MIGRATION_2=PASS'|Add-Content (Join-Path $state 'migration.log'); 'MIGRATION_3=PASS'|Add-Content (Join-Path $state 'migration.log'); 'GUNZSCOPE_SUPPLY_SOURCE=v3'|Set-Content (Join-Path $state 'production.env'); 'RELEASE_HEAD='+$ExpectedReleaseHead|Set-Content (Join-Path $state 'ACTIVE_RUNTIME.json'); 'DEPLOY_RESULT=PASS';'MUTATION_EXECUTED=YES';exit 0}; Assert-ProductionTarget; Assert-Approval $Execute $ApprovalPhrase 'UPDATE_OTG_ANALYTICS_8502'; if($ReleaseCandidateRoot.StartsWith($ExpectedRoot,[StringComparison]::OrdinalIgnoreCase)){throw 'RUNTIME_MUST_BE_OUTSIDE_PRODUCTION'}; if(-not(Test-Path $ReleasePython)){throw 'RELEASE_PYTHON_MISSING'}
$head=(git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot rev-parse HEAD); if($head -ne $ExpectedOldHead){throw 'EXPECTED_OLD_HEAD_MISMATCH'}; if(-not [string]::IsNullOrEmpty((git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot status --porcelain))){throw 'PRODUCTION_WORKTREE_NOT_CLEAN'}; $main=(git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot rev-parse origin/main); $ancestor=$true; if($Execute){git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot merge-base --is-ancestor $ExpectedOldHead $ExpectedReleaseHead 2>$null; $ancestor=($LASTEXITCODE -eq 0)}
"MODE=$(if($Execute){'EXECUTE'}else{'DRY_RUN'})"; "OLD_HEAD=$head"; "RELEASE_HEAD=$ExpectedReleaseHead"; "MAIN_PROMOTION_REQUIRED=$(if($main -ne $ExpectedReleaseHead){'YES'}else{'NO'})"; "RUNTIME_PLAN=PASS"; "ARTIFACT_REFRESH_PLAN=PASS"; "MIGRATION_PLAN_COUNT=3"; "TARGET_PORT=8502"; "FORBIDDEN_TARGET_GUARDS=PASS"; "BACKUP_MANIFEST_REQUIRED=YES"; "RELEASE_ANCESTOR_CHECK=$(if($ancestor){'PASS'}else{'FAIL'})"
if(-not $ancestor){throw 'RELEASE_NOT_DESCENDANT'}; if($Execute -and $main -ne $ExpectedReleaseHead){throw 'MAIN_PROMOTION_REQUIRED'}; if($Execute -and -not(Test-Path $BackupManifest)){throw 'BACKUP_MANIFEST_REQUIRED'}
Invoke-GuardedAction -Execute:$Execute -Name 'REFRESH_MIGRATE_CUTOVER_HEALTH_TASKS' -Action { git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot merge --ff-only $ExpectedReleaseHead }; "MUTATION_EXECUTED=$(if($Execute){'YES'}else{'NO'})"
